.thread-root-message {
    padding: 12px 16px;
    background: #fff;
    border-bottom: 1px solid #e0e0e0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-input-area {
    padding: 12px 16px;
}

hr {
    border: none;
    border-top: 1px solid #e0e0e0;
    margin: 0;
}

